-- BIRD database 'authors' translated to PostgreSQL.
-- Generated by research/advtext2sql/delivery/build.py from the live
-- benchmark server; types, keys and column comments are the server's own.

CREATE TABLE "author" (
    "id" bigint NOT NULL,
    "name" text,
    "affiliation" text,
    PRIMARY KEY ("id")
);

CREATE TABLE "conference" (
    "id" bigint NOT NULL,
    "shortname" text,
    "fullname" text,
    "homepage" text,
    PRIMARY KEY ("id")
);

CREATE TABLE "journal" (
    "id" bigint NOT NULL,
    "shortname" text,
    "fullname" text,
    "homepage" text,
    PRIMARY KEY ("id")
);

CREATE TABLE "paper" (
    "id" bigint NOT NULL,
    "title" text,
    "year" bigint,
    "conferenceid" bigint,
    "journalid" bigint,
    "keyword" text,
    PRIMARY KEY ("id")
);

CREATE TABLE "paperauthor" (
    "paperid" bigint,
    "authorid" bigint,
    "name" text,
    "affiliation" text
);

